query Search($query: String!, $filters: Filters) {
  search(query: $query, filters: $filters) {
    type
    class {
      objectId
      name
    }
    subject {
      objectId
      name
    }
    theme {
      objectId
      name
    }
    subtheme {
      objectId
      name
    }
    subthemes {
      type
      class {
        objectId
        name
      }
      subject {
        objectId
        name
      }
      theme {
        objectId
        name
      }
      subtheme {
        objectId
        name
      }
    }
  }
}
